/**
 * The Tallaby Classic template (PLAN.md P4-03, §8.1): today's storefront as
 * a SiteConfig. New stores start from it, and `0062` seeds it as
 * `template_versions` v2 (generated by `scripts/classic-template-sql.ts`;
 * a test keeps the two in sync). No React here.
 */
import { SITE_CONFIG_VERSION, type PageContent, type SectionInstance, type SiteConfigInput } from "../config/schema";

export const TALLABY_CLASSIC_KEY = "tallaby-classic";
/** Bump together with a new `template_versions` row. */
export const TALLABY_CLASSIC_VERSION = 2;

const section = (id: string, sectionId: string, props: Record<string, unknown> = {}): SectionInstance => ({
  id,
  sectionId,
  version: 1,
  props,
});

export function classicHeader(): SectionInstance {
  return section("classic-header", "classic-header");
}

export function classicFooter(): SectionInstance {
  return section("classic-footer", "classic-footer");
}

export function classicHomeContent(): PageContent {
  return {
    sections: [
      section("classic-hero", "classic-hero"),
      section("classic-categories", "classic-categories", { title: "" }),
      section("classic-catalog", "classic-catalog"),
    ],
  };
}

export function tallabyClassicConfig(): SiteConfigInput {
  return {
    schemaVersion: SITE_CONFIG_VERSION,
    designSystem: { colors: {}, typography: {}, spacing: {} },
    header: classicHeader(),
    footer: classicFooter(),
    settings: { defaultLocale: "ar", locales: ["ar", "en"] },
    pages: [{ slug: "home", isHome: true, name: "الرئيسية", seo: {}, content: classicHomeContent() }],
  };
}
